const stock=(id,width=900)=>`https://images.unsplash.com/${id}?auto=format&fit=crop&w=${width}&q=85`;
const covers={lock:stock('photo-1504148455328-c376907d081c'),computer:stock('photo-1517694712202-14dd9538aa97'),electric:stock('photo-1621905251189-08b45d6a269e'),plumbing:stock('photo-1581578731548-c64695cc6952'),other:stock('photo-1530124566582-a618bc2615dc')};
const portraits=['photo-1500648767791-00dcc994a43e','photo-1506794778202-cad84cf45f1d','photo-1472099645785-5658abf4ff4e','photo-1519085360753-af0119f7cbe7'];
const titles={lock:'দরজার তালা ও ক্লোজার লাগিয়ে দেব',computer:'আপনার কম্পিউটার কাজের জন্য তৈরি করে দেব',electric:'ফ্যান, লাইট ও সুইচের কাজ করে দেব',plumbing:'কল ও পানির লাইনের সমস্যা ঠিক করে দেব',other:'শেলফ, পর্দার রড ও ফার্নিচার লাগিয়ে দেব'};
workers.forEach((w,i)=>Object.assign(w,{photo:stock(portraits[i%4],160),cover:covers[w.cat],title:titles[w.cat],years:[6,4,8,5,3,7,4,5][i],completed:[38,26,47,29,19,34,15,22][i],gallery:[covers[w.cat],w.cat==='computer'?stock('photo-1496181133206-80ce9b88a853'):covers.other],history:[{title:w.skills[0],area:w.area,date:'সেপ্টেম্বর ২০২৬',amount:w.rate},{title:w.skills[1],area:w.area,date:'আগস্ট ২০২৬',amount:w.rate+150}]}));
let savedWorkers=[];try{const saved=JSON.parse(localStorage.getItem('mishtry-saved')||'[]');if(Array.isArray(saved))savedWorkers=saved.filter(id=>Number.isSafeInteger(id))}catch{}
let customer=null,pendingHire=false,draftMedia={photo:null,images:[],video:null},mediaURLs=[],recorder=null,recordStream=null,recordTimer=null,editorValues={};
try{customer=JSON.parse(sessionStorage.getItem('mishtry-customer')||'null')}catch{}
function matches(w){const q=$('#query').value.trim().toLowerCase();return(category==='all'||w.cat===category)&&(!$('#available').checked||w.available)&&(!q||[w.name,w.title,w.keywords,...w.skills].join(' ').toLowerCase().includes(q))}
function picture(src,alt,cls=''){if(!src)return '';return `<img class="${cls}" src="${escapeHTML(src)}" alt="${escapeHTML(alt)}" loading="lazy" onerror="this.style.display='none';this.parentElement.classList.add('image-unavailable')">`}
render=function(){const place=places[$('#location').value],radius=+$('#radius').value;const list=workers.map(w=>({...w,distance:distance(w,place)})).filter(w=>matches(w)&&w.distance<=radius&&(!$('#saved-only').checked||savedWorkers.includes(w.id))).sort((a,b)=>$('#sort').value==='rate'?a.rate-b.rate:$('#sort').value==='rating'?b.rating-a.rating:a.distance-b.distance);$('#result-count').textContent=bn(list.length);$('#result-summary').textContent=`${place.name} · ${bn(radius)} কিমির মধ্যে · ${bn(list.length)}টি কাজের কার্ড`;$('#workers').innerHTML=list.length?list.map(w=>`<article class="gig-card"><button class="gig-cover" data-profile="${w.id}" aria-label="${escapeHTML(w.title)} — ${escapeHTML(w.name)}">${picture(w.cover,'কাজের কার্ডের উদাহরণ ছবি')}<span class="cover-label">${w.local?(w.gallery.length?'নিজের খসড়া':'খসড়া · নমুনা কভার'):'নমুনা কাজের কার্ড'}</span><span class="cover-type">${escapeHTML(w.skills[0])}</span><span class="cover-arrow">↗</span></button><div class="gig-body"><div class="gig-person"><div class="face">${picture(w.photo,'প্রোফাইলের উদাহরণ ছবি')}<span>${w.initial}</span></div><div><button class="name-button" data-profile="${w.id}">${escapeHTML(w.name)}</button><small>⌖ ${w.area} · ${bn(w.distance.toFixed(1))} কিমি</small></div><span class="online-dot ${w.available?'':'offline'}" title="${w.available?'আজ উপলব্ধ':'আজ উপলব্ধ নয়'}"></span></div><button class="gig-title" data-profile="${w.id}">${escapeHTML(w.title)}</button><div class="gig-meta"><span class="rating">★ ${w.local?'নতুন':bn(w.rating)} <small>${w.local?'রিভিউ নেই':`(${bn(w.reviews)} নমুনা)`}</small></span><span>${w.local?'খসড়া প্রোফাইল':`${bn(w.completed)} কাজ · নমুনা`}</span></div><div class="gig-footer"><div><small>শুরু</small> <strong>৳${bn(w.rate)}</strong> <small>/ কাজ</small></div><button data-profile="${w.id}" class="profile-link">প্রোফাইল দেখুন ↗</button></div><div class="gig-actions"><button class="hire-action" data-hire="${w.id}" aria-label="${escapeHTML(w.name)}-কে হায়ার করুন"><span class="hire-light" aria-hidden="true"></span> হায়ার করুন <span class="hire-arrow" aria-hidden="true">↗</span></button><button class="save-action ${savedWorkers.includes(w.id)?'is-saved':''}" data-save="${w.id}" aria-pressed="${savedWorkers.includes(w.id)}" aria-label="${escapeHTML(w.name)}-এর কার্ড ${savedWorkers.includes(w.id)?'সেভ তালিকা থেকে সরান':'সেভ করুন'}"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 3h12v18l-6-4-6 4Z"/></svg><span>${savedWorkers.includes(w.id)?'সেভ হয়েছে':'সেভ করুন'}</span></button></div></div></article>`).join(''):`<div class="empty"><h3>এই খোঁজে কোনো কাজের কার্ড নেই</h3><p>অন্য দক্ষতা লিখুন বা দূরত্ব বাড়ান।</p><button class="outline" id="reset">সব ফিল্টার মুছুন</button></div>`;$('#booking-count').textContent=bn(bookings.length);$('#saved-count').textContent=bn(workers.filter(w=>savedWorkers.includes(w.id)).length);for(const key of ['mirpur','dhanmondi','uttara']){$(`#count-${key}`).textContent=bn(workers.filter(w=>matches(w)&&distance(w,places[key])<=3).length)}$('#map-total').textContent=bn(workers.filter(matches).length);document.querySelectorAll('[data-area]').forEach(b=>{b.classList.toggle('chosen',b.dataset.area===$('#location').value);b.setAttribute('aria-pressed',b.dataset.area===$('#location').value)});$('#customer').textContent=customer?`${customer.name} · গ্রাহক`:'সাইন ইন / অ্যাকাউন্ট';};
const baseShow=show;show=function(html){$('#modal').classList.remove('wide');baseShow(html)};
profile=function(id){selectedWorker=workers.find(w=>w.id===id);const w=selectedWorker;show(`<div class="profile-cover" style="background-image:linear-gradient(90deg,#193b31e8,#193b3150),url('${escapeHTML(w.cover)}')"><span>${w.local?'নিজের প্রোফাইলের খসড়া':'কর্মীর প্রোফাইল · সব তথ্য নমুনা'}</span><h2>${escapeHTML(w.title)}</h2></div>${w.local?'<button class="outline full" id="join">খসড়া প্রোফাইল সম্পাদনা করুন</button>':''}<div class="profile-layout"><div class="profile-main"><div class="profile-identity"><div class="large-face">${picture(w.photo,'প্রোফাইল ছবি')}<span>${w.initial}</span></div><div><h2>${escapeHTML(w.name)}</h2><p>⌖ ${w.area} <span>·</span> ${w.available?'আজ উপলব্ধ':'আগামীকাল উপলব্ধ'}</p></div></div><div class="profile-stats"><div><strong>${w.local?'নতুন':bn(w.rating)+' ★'}</strong><small>${w.local?'রিভিউ নেই':'নমুনা রেটিং'}</small></div><div><strong>${bn(w.completed)}</strong><small>${w.local?'সম্পন্ন কাজ':'নমুনা সম্পন্ন কাজ'}</small></div><div><strong>${bn(w.years)} বছর</strong><small>${w.local?'নিজের দেওয়া অভিজ্ঞতা':'নমুনা অভিজ্ঞতা'}</small></div></div><div class="profile-section"><h3>আমার সম্পর্কে</h3><p>${escapeHTML(w.bio)}</p><div class="tags">${w.skills.map(s=>`<span>${escapeHTML(s)}</span>`).join('')}</div></div><div class="profile-section"><h3>কাজের ছবি ও পোর্টফোলিও</h3><p>${w.local?'আপনার বেছে নেওয়া ছবি। এখনও প্রকাশিত নয়।':'সাজসজ্জার নমুনা ছবি, এই কর্মীর কাজের প্রমাণ নয়।'}</p>${!w.gallery.length?'<p>এখনও কাজের ছবি যোগ করা হয়নি। প্রোফাইল সম্পাদনা করে ছবি যোগ করুন।</p>':''}<div class="portfolio-grid">${w.gallery.map((src,i)=>`<button data-gallery="${i}" aria-label="কাজের ছবি ${bn(i+1)} বড় করে দেখুন">${picture(src,'কাজের উদাহরণ')}<span>${escapeHTML(w.skills[i%w.skills.length])} ↗</span></button>`).join('')}</div></div><div class="profile-section"><h3>ভিডিও পরিচিতি</h3>${w.video?`<video controls playsinline preload="metadata" src="${escapeHTML(w.video)}"></video>`:`<div class="video-empty"><span>▷</span><div><strong>নিজের কাজ, নিজের কথায়</strong><p>এই নমুনা প্রোফাইলে ভিডিও নেই। কর্মী প্রোফাইল তৈরির সময় ভিডিও আপলোড বা রেকর্ড করা যাবে।</p></div></div>`}</div><div class="profile-section"><h3>কাজের ইতিহাস ${w.local?'':'· নমুনা'}</h3>${w.history.length?w.history.map(h=>`<div class="history-row"><span class="history-icon">✓</span><div><strong>${escapeHTML(h.title)}</strong><small>${escapeHTML(h.area)} · ${h.date}</small></div><b>৳${bn(h.amount)}</b></div>`).join(''):'<p>এখনও কোনো সম্পন্ন কাজ নেই।</p>'}</div><div class="profile-section"><h3>গ্রাহকের রিভিউ ${w.local?'':'· নমুনা'}</h3>${w.local?'<p>প্রথম কাজের পর রিভিউ পাওয়া যাবে।</p>':`<div class="review-box"><span class="rating">★★★★★</span><p>“${w.review}”</p><small>নমুনা গ্রাহক · বাস্তব অভিজ্ঞতা নয়</small></div>`}</div></div><aside class="hire-panel"><div class="eyebrow">কাজের প্রাথমিক রেট</div><h2>৳${bn(w.rate)} <small>থেকে</small></h2><p>${escapeHTML(w.skills[0])}</p><ul><li>কাজের বিস্তারিত আগে আলোচনা</li><li>সময় ও চূড়ান্ত মূল্য নিশ্চিত করুন</li><li>যন্ত্রাংশের খরচ আলাদা হতে পারে</li></ul><button class="primary full" id="hire">কাজের অনুরোধ করুন →</button><button class="outline full" id="contact">কথা বলুন</button><div class="verification-note">◌ পরিচয় ও দক্ষতা যাচাই হয়নি</div><p class="mini">এটি ডেমো। অনুরোধ বা পেমেন্ট বাস্তবে পাঠানো হবে না।</p></aside></div>`);$('#modal').classList.add('wide');};
function customerForm(hire=false){pendingHire=hire;if(customer&&!hire){show(`<div class="eyebrow">গ্রাহকের ডেমো প্রোফাইল</div><h2>${escapeHTML(customer.name)}</h2><p>নাম ও ফোন দিয়ে তৈরি স্থানীয় ডেমো সেশন। ফোন যাচাই বা বাস্তব অ্যাকাউন্ট তৈরি হয়নি।</p><button class="primary full" id="view-bookings">আমার বুকিং দেখুন</button><button class="outline full" id="logout">ডেমো সেশন শেষ করুন</button>`);return}show(`<div class="eyebrow">কাজ করাবেন? শুরুটা সহজ।</div><h2>শুধু নাম আর ফোন নম্বর</h2><p>প্রোফাইল দেখে পছন্দ করুন, তারপর কাজের অনুরোধ দিন।</p><form id="customer-form"><label>আপনার নাম<input name="name" autocomplete="name" required minlength="2" maxlength="60" placeholder="ডেমোর জন্য নমুনা নাম"></label><label>ফোন নম্বর<input name="phone" type="tel" inputmode="tel" required pattern="01[3-9][0-9]{8}" maxlength="11" placeholder="01XXXXXXXXX" aria-describedby="phone-help"></label><small id="phone-help">১১ সংখ্যার বাংলাদেশি মোবাইল নম্বরের ফরম্যাট। পরীক্ষায় নমুনা নম্বর ব্যবহার করুন।</small><div class="notice">ডেমোতে OTP পাঠানো হবে না। ফোন নম্বর সংরক্ষণ বা পাঠানো হয় না। নাম শুধু এই ট্যাবের সেশনে থাকবে।</div><button class="primary full">${hire?'ডেমো প্রোফাইল তৈরি করে কাজ দিন':'ডেমো প্রোফাইল তৈরি করুন'} →</button></form>`)}
join=function(){show(`<div class="eyebrow">কর্মীর প্রোফাইল স্টুডিও · ডেমো</div><h2>আপনার কাজই হোক আপনার পরিচয়</h2><p>একটি দক্ষতা দিয়ে শুরু করুন। ছবি ও ভিডিও দিয়ে কাজের মান তুলে ধরুন।</p><form id="worker-form"><div class="editor-grid"><div><label>আপনার নাম<input name="name" required maxlength="60" value="${escapeHTML(editorValues.name||'')}" placeholder="নমুনা নাম"></label><label>কাজের কার্ডের শিরোনাম<input name="title" required maxlength="100" value="${escapeHTML(editorValues.title||'')}" placeholder="যেমন: দরজার তালা ও ক্লোজার লাগিয়ে দেব"></label><div class="field-pair"><label>দক্ষতার ধরন<select name="cat"><option value="lock">তালা ও দরজা</option><option value="computer">কম্পিউটার</option><option value="electric">ইলেকট্রিক</option><option value="plumbing">পানির লাইন</option><option value="other">আরও ছোট কাজ</option></select></label><label>এলাকা<select name="area"><option value="mirpur">মিরপুর</option><option value="dhanmondi">ধানমন্ডি</option><option value="uttara">উত্তরা</option></select></label></div><div class="field-pair"><label>শুরুর রেট (৳)<input type="number" name="rate" min="1" max="100000" required value="${editorValues.rate||350}"></label><label>অভিজ্ঞতা (বছর)<input type="number" name="years" min="0" max="60" required value="${editorValues.years||1}"></label></div><label>আপনার দক্ষতাগুলো<input name="skills" required maxlength="160" value="${escapeHTML(editorValues.skills||'')}" placeholder="কমা দিয়ে লিখুন: তালা, ক্লোজার, কবজা"></label><label>নিজের ও কাজের বিবরণ<textarea name="bio" required minlength="10" maxlength="800" placeholder="কী কাজ করেন, কীভাবে করেন…">${escapeHTML(editorValues.bio||'')}</textarea></label></div><div class="media-editor"><h3>ছবি ও ভিডিও</h3><p>ফাইল শুধু এই ব্রাউজারে প্রিভিউ হবে। কোথাও আপলোড বা প্রকাশ হবে না।</p><label class="upload-tile">◉ প্রোফাইল ছবি<input id="portrait-upload" type="file" accept="image/jpeg,image/png,image/webp"><small>JPG, PNG, WebP · সর্বোচ্চ ৫ MB</small></label><div id="portrait-preview"></div><label class="upload-tile">▧ কাজের ছবি / গিগ কভার<input id="work-upload" type="file" multiple accept="image/jpeg,image/png,image/webp"><small>সর্বোচ্চ ৪টি ছবি · প্রতিটি ৫ MB</small></label><div id="work-preview" class="upload-thumbs"></div><label class="upload-tile">▷ ভিডিও পরিচিতি<input id="video-upload" type="file" accept="video/mp4,video/webm,video/quicktime"><small>MP4, WebM, MOV · সর্বোচ্চ ৩০ MB</small></label><div class="record-actions"><button type="button" class="outline" id="record">◉ ক্যামেরায় রেকর্ড করুন</button><button type="button" class="outline" id="stop-record" hidden>■ রেকর্ড শেষ করুন</button></div><p id="media-status" role="status"></p><video id="video-preview" controls playsinline hidden></video></div></div><div class="notice">কাজের ইতিহাস ও রেটিং নিজে লিখতে পারবেন না—লাইভ সংস্করণে সম্পন্ন বুকিং ও গ্রাহকের রিভিউ থেকে আসবে। এখন নতুন খসড়ায় দুটোই শূন্য থাকবে। পৃষ্ঠা রিলোড করলে খসড়া ও মিডিয়া মুছে যাবে।</div><button class="primary full">আমার কাজের কার্ডের প্রিভিউ তৈরি করুন →</button></form>`);$('#modal').classList.add('wide');if(editorValues.cat)$('#worker-form [name=cat]').value=editorValues.cat;if(editorValues.area)$('#worker-form [name=area]').value=editorValues.area;refreshMedia()};
function refreshMedia(){if(!$('#portrait-preview'))return;$('#portrait-preview').innerHTML=draftMedia.photo?picture(draftMedia.photo,'নিজের প্রোফাইল ছবি','preview-face'):'';$('#work-preview').innerHTML=draftMedia.images.map(s=>picture(s,'নিজের কাজের ছবি')).join('');const v=$('#video-preview');v.hidden=!draftMedia.video;if(draftMedia.video)v.src=draftMedia.video}
function blobURL(file){const u=URL.createObjectURL(file);mediaURLs.push(u);return u}
function stopRecording(){if(recorder&&recorder.state!=='inactive')recorder.stop();if(recordStream)recordStream.getTracks().forEach(t=>t.stop());recordStream=null;clearTimeout(recordTimer)}
$('#modal').addEventListener('close',()=>{stopRecording();$('#modal-content').querySelectorAll('video').forEach(v=>v.pause())});
document.addEventListener('change',e=>{if(!['portrait-upload','work-upload','video-upload'].includes(e.target.id))return;const files=[...e.target.files],video=e.target.id==='video-upload';if(!files.length)return;const allowed=video?/^video\/(mp4|webm|quicktime)$/:/^image\/(jpeg|png|webp)$/;if(files.length>4||files.some(f=>!allowed.test(f.type)||f.size>(video?30:5)*1024*1024)){$('#media-status').textContent='ফাইলের ধরন, সংখ্যা বা আকার অনুমোদিত সীমার বাইরে। আবার বেছে নিন।';e.target.value='';return}if(video)draftMedia.video=blobURL(files[0]);else if(e.target.id==='portrait-upload')draftMedia.photo=blobURL(files[0]);else draftMedia.images=files.map(blobURL);$('#media-status').textContent='ফাইল বেছে নেওয়া হয়েছে। শুধু স্থানীয় প্রিভিউ।';refreshMedia()});
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.save){const id=+b.dataset.save;const wasSaved=savedWorkers.includes(id);savedWorkers=wasSaved?savedWorkers.filter(x=>x!==id):[...savedWorkers,id];try{localStorage.setItem('mishtry-saved',JSON.stringify(savedWorkers.filter(id=>workers.some(w=>w.id===id&&!w.local))))}catch{}render();const next=document.querySelector('[data-save="'+id+'"]');if(next)next.focus();else $('#saved-only').focus();return}if(b.dataset.hire){selectedWorker=workers.find(w=>w.id===+b.dataset.hire);if(!selectedWorker)return;if(!customer)customerForm(true);else bookingForm();return}if(b.id==='reset')$('#saved-only').checked=false;if(b.id==='hire'){e.stopImmediatePropagation();if(!customer)customerForm(true);else bookingForm();return}if(b.id==='customer')customerForm();if(b.id==='logout'){customer=null;sessionStorage.removeItem('mishtry-customer');render();$('#modal').close()}if(b.dataset.area){$('#location').value=b.dataset.area;$('#radius').value=b.dataset.area==='dhaka'?'30':'3';render();$('#results').scrollIntoView({behavior:'smooth',block:'start'})}if(b.dataset.query){$('#query').value=b.dataset.query;category='all';document.querySelectorAll('[data-cat]').forEach(x=>{x.classList.toggle('selected',x.dataset.cat==='all');x.setAttribute('aria-pressed',x.dataset.cat==='all')});render();$('#results').scrollIntoView({behavior:'smooth'})}if(b.dataset.gallery){const src=selectedWorker.gallery[+b.dataset.gallery];show(`<h2>কাজের ছবি</h2>${picture(src,'বড় করে কাজের ছবি','lightbox-photo')}<p>${selectedWorker.local?'নিজের খসড়ার ছবি':'নমুনা ছবি · সম্পন্ন কাজের প্রমাণ নয়'}</p><button class="outline full" data-profile="${selectedWorker.id}">প্রোফাইলে ফিরে যান</button>`)}if(b.id==='record'){if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){$('#media-status').textContent='এই ব্রাউজারে রেকর্ডিং উপলব্ধ নয়। ভিডিও ফাইল বেছে নিন।';return}b.disabled=true;try{recordStream=await navigator.mediaDevices.getUserMedia({video:true,audio:true});if(!$('#modal').open||!$('#video-preview')){stopRecording();return}const chunks=[];recorder=new MediaRecorder(recordStream);recorder.ondataavailable=ev=>{if(ev.data.size)chunks.push(ev.data)};recorder.onstop=()=>{const blob=new Blob(chunks,{type:recorder.mimeType});if(blob.size<=30*1024*1024)draftMedia.video=blobURL(blob);const v=$('#video-preview');if(v){v.srcObject=null;v.muted=false;$('#media-status').textContent=blob.size>30*1024*1024?'ভিডিও ৩০ MB-এর বেশি হয়েছে। ছোট করে আবার রেকর্ড করুন।':'রেকর্ডিং শেষ। শুধু স্থানীয় প্রিভিউ।';$('#record').disabled=false;$('#stop-record').hidden=true;refreshMedia()}};const v=$('#video-preview');v.hidden=false;v.srcObject=recordStream;v.muted=true;await v.play();recorder.start();$('#stop-record').hidden=false;$('#media-status').textContent='রেকর্ড হচ্ছে… সর্বোচ্চ ৬০ সেকেন্ড।';recordTimer=setTimeout(stopRecording,60000)}catch{stopRecording();b.disabled=false;$('#media-status').textContent='ক্যামেরা বা মাইক্রোফোন পাওয়া যায়নি। অনুমতি দিন অথবা ভিডিও ফাইল বেছে নিন।'}}if(b.id==='stop-record')stopRecording()},true);
document.addEventListener('submit',e=>{if(e.target.id==='customer-form'){e.preventDefault();e.stopImmediatePropagation();const f=new FormData(e.target);customer={name:f.get('name').trim()};try{sessionStorage.setItem('mishtry-customer',JSON.stringify(customer))}catch{}render();if(pendingHire)bookingForm();else customerForm();}if(e.target.id==='worker-form'){e.preventDefault();e.stopImmediatePropagation();if(recorder&&recorder.state==='recording'){$('#media-status').textContent='আগে রেকর্ড শেষ করুন, তারপর প্রিভিউ তৈরি করুন।';return}editorValues=Object.fromEntries(new FormData(e.target));const d=editorValues,p=places[d.area],old=workers.find(w=>w.local),id=old?old.id:Date.now();const w={id,local:true,name:d.name,initial:d.name.slice(0,1),area:p.name,cat:d.cat,skills:d.skills.split(',').map(x=>x.trim()).filter(Boolean),title:d.title,bio:d.bio,rate:+d.rate,years:+d.years,rating:0,reviews:0,completed:0,available:true,lat:p.lat,lng:p.lng,keywords:d.skills,photo:draftMedia.photo,cover:draftMedia.images[0]||covers[d.cat],gallery:[...draftMedia.images],video:draftMedia.video,history:[]};if(old)workers.splice(workers.indexOf(old),1,w);else workers.push(w);$('#query').value='';$('#location').value=d.area;$('#radius').value='3';category='all';document.querySelectorAll('[data-cat]').forEach(x=>{x.classList.toggle('selected',x.dataset.cat==='all');x.setAttribute('aria-pressed',x.dataset.cat==='all')});render();profile(id)}},true);
$('#saved-only').addEventListener('change',render);
$('#search-form').addEventListener('submit',()=>$('#results').scrollIntoView({behavior:'smooth'}));
document.querySelectorAll('[data-cat]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.cat==='all'));render();
